#pragma once

// LTBF R41 (macOS): the jackhumbert fork's entIComponent.hpp (deps/red4ext.sdk, "generated by Jack") on top of the macOS SDK.
// It replaces the macOS SDK's data-only IComponent for this plugin, because FlightComponent overrides IComponent and gameComponent
// virtuals. Changes from the fork:
//  - the owner pointer is reachable as both `entity` (fork name, used by LTBF) and `owner` (macOS SDK name, used by SDK headers);
//  - no tail padding member on macOS: the game reuses IComponent's tail padding (macOS SDK, Detail::DataSize), and the macOS SDK's
//    generated component headers place their first member with Detail::DataSize<ent::IComponent>;
//  - IGameInstance and CallbackManager are forward declared (the macOS SDK has neither header);
//  - the base implementations that call the game ("VFT hash + Windows slot") resolve on macOS through ltbf_mac_vft_slot
//    (macos/MacShims.cpp), which maps each slot to the macOS function found in R40 (Windows slot + 8 from 0x20 on).
// Virtual order is the fork's (Windows) order; clang's Itanium layout gives the destructor two slots, which is the macOS game's
// layout too, so every slot after ISerializable's destructor lands at Windows + 8 by construction.

#include <cstdint>
#include <RED4ext/Common.hpp>
#include <RED4ext/CName.hpp>
#include <RED4ext/Handle.hpp>
#include <RED4ext/NativeTypes.hpp>
#include <RED4ext/Relocation.hpp>
#include <RED4ext/Scripting/IScriptable.hpp>
#include <RED4ext/Scripting/Natives/Generated/Transform.hpp>
#include <RED4ext/Scripting/Natives/Generated/ent/IAttachment.hpp>
#include <RED4ext/Scripting/Natives/ScriptGameInstance.hpp>
#include <RED4ext/SharedSpinLock.hpp>

namespace RED4ext
{
struct IGameInstance;
struct CallbackManager;
struct WorldTransform;
namespace game
{
struct PersistentState;
}
namespace ent
{
struct Entity;
struct IComponentState;

struct IComponent : IScriptable
{
    static constexpr const char* NAME = "entIComponent";
    static constexpr const char* ALIAS = "IComponent";

    /// @hash 1586431952:idata
    static constexpr const uintptr_t VFT = 1586431952;

    inline virtual void* sub_C0(void* a1) override
    {
        static UniRelocFunc<decltype(&IComponent::sub_C0)> call(VFT, 0xC0);
        return call(this, a1);
    }

    virtual void sub_108() { };
    // get property value when it's a Handle<IBinding>, assign to out
    virtual bool sub_110(CName propertyName, void* out);
    // get property value when it's a Handle<IBinding> and something is CResource, assign to out
    virtual bool sub_118(CName propertyName, void* out);
    virtual void sub_120() { };
    virtual bool sub_128() { return false; };
    virtual bool sub_130() { return true; };
    virtual void sub_138() { };
    // after callback is registered
    virtual void sub_140() { };
    // called in Entity/Remove And Reapply
    virtual void sub_148(void * componentHelper) { };
    // Get persistent state
#ifdef __APPLE__
    // LTBF R42f (macOS): the game returns this Handle by value through x8 (game 0x1F295E4 `mov x19,x8` ... `str q0,[x19]`; IComponent 0xCA6E44 `stp xzr,xzr,[x8]`), so the Windows form wrote through a leftover x8 (Grok Bot audit, verified by Claude).
    virtual Handle<game::PersistentState> sub_150();
#else
    virtual Handle<game::PersistentState>* sub_150(Handle<game::PersistentState>*);
#endif
    // called on initialize components (checks isReplicable)
    virtual bool sub_158();
    // IsReplicable
    virtual bool sub_160();
    // OnMeshesLoaded
    virtual void sub_168() { };
    struct CompInit {
        Transform transform;            // 00
        ent::Entity * entity;           // 20
        IGameInstance * gameInstance;   // 28
    };
    virtual uint64_t Initialize(CompInit* a1); // 170
    virtual void Uninitialize(ScriptGameInstance* scriptGameInstance);  // 178
    virtual void OnAttach(void*);                                       // 180
    virtual void HasAttached() { };                                     // 188
    virtual void OnDetach(void* ComponentAttachContext);                // 190
    virtual void OnEntityLODUpdated(void* entityUnk158) { };            // 198
    virtual void sub_1A0() { };
    virtual void OnPostSnapshotApplied() { };                           // 1A8
    virtual void sub_1B0() { };
    virtual void OnIncomingAttachmentAdded(Handle<IAttachment>*) { };   // 1B8
    virtual void OnIncomingAttachmentRemoved(Handle<IAttachment>*) { }; // 1C0
    virtual void OnOutgoingAttachmentAdded(Handle<IAttachment>*) { };   // 1C8
    virtual void OnOutgoingAttachmentRemoved(Handle<IAttachment>*) { }; // 1D0
    virtual bool sub_1D8() { return true; };
    // called from Toggle when (flags & 2) == 0
    virtual void OnEnabled(bool enabled) { };                           // 1E0
    // called on gather event listeners, after registered
    virtual void sub_1E8(Handle<CallbackManager>*) { };
    virtual void sub_1F0() { };
    virtual uint64_t OnRenderSelection(uint64_t);                       // 1F8
    virtual void sub_200() { };
    virtual void OnRequestComponents(void *) { };                       // 208
    virtual void OnTakeControl(void*) { };                              // 210
    virtual void sub_218(void*) { };
    virtual const char * GetBucketString();                             // 220
    virtual CClass* GetReplicatedStateClass();                          // 228

    struct Flags
    {
        uint8_t Initialized : 1;    // 01
        uint8_t Attached : 1;       // 02
        uint8_t Unk04 : 1;          // 04
        uint8_t Unk08 : 1;          // 08
    };

    CName name; // 40
    CName appearanceName; // 48
    union
    {
        Entity* entity; // 50 (fork name)
        Entity* owner;  // 50 (macOS SDK name)
    };
    ent::IComponentState* replicatedState; // 58
    CRUID id; // 60
    ResourcePath appearancePath; // 68
    DynArray<Handle<ent::IAttachment>> attachments; // 70
    uint16_t transform_offset; // 80
    uint16_t unk82;
    uint32_t unk84;
    Flags flags; // 88
    uint8_t unk89;
    uint8_t unk8A;
    bool isEnabled; // 8B
    bool isReplicable; // 8C
#if !defined(__APPLE__)
    uint8_t unk8D[0x90 - 0x8D]; // 8D
#endif
};
RED4EXT_ASSERT_OFFSET(IComponent, entity, 0x50);
RED4EXT_ASSERT_OFFSET(IComponent, id, 0x60);
RED4EXT_ASSERT_OFFSET(IComponent, attachments, 0x70);
RED4EXT_ASSERT_OFFSET(IComponent, isEnabled, 0x8B);
RED4EXT_ASSERT_OFFSET(IComponent, isReplicable, 0x8C);
static_assert(sizeof(IComponent) == 0x90, "entIComponent size");
} // namespace ent
} // namespace RED4ext

#ifdef RED4EXT_HEADER_ONLY
#include <RED4ext/Scripting/Natives/entIComponent-inl.hpp>
#endif
